<div v-else-if=\"cell.day.absence\" class=\"mi\" :class=\"absMiClass(cell.day.absence.type)\">\n                        {{ cell.day.absence.typeName }}\n                    </div>\n                    <div v-else-if=\"cell.day.entries.length\" class=\"hh\">{{ hoursLabel(cell.day) }}</div>\n                </template>\n            </div>\n        </div>\n        <div class=\"leg\">\n            <span><span class=\"dot vacation\" /> {{ t('zeitwerk', 'Urlaub') }}</span>\n            <span><span class=\"dot holiday\" /> {{ t('zeitwerk', 'Feiertag') }}</span>\n            <span><span class=\"dot sick\" /> {{ t('zeitwerk', 'Krank') }}</span>\n            <span><span class=\"dot other\" /> {{ t('zeitwerk', 'Erfasst') }}</span>\n        </div>\n    </div>\n</template>\n\n<script>\nimport { getDaysInMonth } from '../utils/dateUtils.js'\nimport { formatMinutes } from '../utils/timeUtils.js'\nimport { getAbsenceColorClass } from '../utils/formatters.js'\n\nexport default {\n    name: 'MonthCalendar',\n    props: {\n        days: {\n            type: Array,\n            default: () => [],\n        },\n        year: {\n            type: Number,\n            required: true,\n        },\n        month: {\n            type: Number,\n            required: true,\n        },\n        selectedDate: {\n            type: String,\n            default: null,\n        },\n    },\n    emits: ['select'],\n    computed: {\n        dayNames() {\n            return [\n                this.t('zeitwerk', 'Mo'), this.t('zeitwerk', 'Di'), this.t('zeitwerk', 'Mi'),\n                this.t('zeitwerk', 'Do'), this.t('zeitwerk', 'Fr'), this.t('zeitwerk', 'Sa'),\n                this.t('zeitwerk', 'So'),\n            ]\n        },\n        cells() {\n            const cells = []\n            const firstDow = new Date(this.year, this.month - 1, 1).getDay() // 0=Sun\n            const lead = (firstDow + 6) % 7 // Mon-start leading count\n            const prevMonth = this.month === 1 ? 12 : this.month - 1\n            const prevYear = this.month === 1 ? this.year - 1 : this.year\n            const prevDays = getDaysInMonth(prevYear, prevMonth)\n\n            // Leading days (previous month, out)\n            for (let i = lead - 1; i >= 0; i--) {\n                cells.push({ num: prevDays - i, out: true, clickable: false })\n            }\n\n            // In-month days (alle anklickbar – auch Wochenende/Feiertag bebuchbar)\n            for (const day of this.days) {\n                cells.push({ num: day.day, day, clickable: true })\n            }\n\n            // Trailing days (next month, out) to complete the last week\n            while (cells.length % 7 !== 0) {\n                cells.push({ num: cells.length % 7, out: true, clickable: false, trailing: true })\n            }\n\n            // Fix trailing numbering (1,2,3...)\n            let t = 1\n            for (const c of cells) {\n                if (c.trailing) c.num = t++\n            }\n\n            return cells\n        },\n    },\n    methods: {\n        hoursLabel(day) {\n            return formatMinutes(day.totalMinutes)\n        },\n        shortName(name) {\n            return name.length > 11 ? name.slice(0, 9) + '.' : name\n        },\n        absenceColorClass: getAbsenceColorClass,\n        absMiClass(type) {\n            return getAbsenceColorClass(type)\n        },\n        cellClasses(cell) {\n            if (cell.out) return 'out'\n            const classes = []\n            if (cell.day.isWeekend) classes.push('we')\n            if (cell.day.isToday) classes.push('today')\n            if (cell.day.date === this.selectedDate) classes.push('sel')\n            return classes\n        },\n        onCellClick(cell) {\n            if (cell.clickable && cell.day) {\n                this.$emit('select', cell.day.date)\n            }\n        },\n    },\n}\n</script>\n\n<style scoped>\n.month-cal.card {\n    background: var(--color-main-background);\n    border: 1px solid var(--color-border-dark, var(--color-border));\n    border-radius: var(--border-radius-large, 12px);\n    padding: 16px;\n}\n\n.cal-grid {\n    display: grid;\n    grid-template-columns: repeat(7, 1fr);\n    gap: 6px;\n}\n\n.cal-dow {\n    margin-bottom: 6px;\n}\n\n.dow {\n    font-size: 13px;\n    font-weight: 600;\n    color: var(--color-main-text);\n    text-align: center;\n    padding: 2px 0;\n}\n\n.cell {\n    aspect-ratio: 1 / 0.92;\n    border: 1px solid var(--color-border-light, var(--color-border));\n    border-radius: var(--border-radius);\n    padding: 7px;\n    font-size: 12px;\n    display: flex;\n    flex-direction: column;\n    cursor: pointer;\n    background: var(--color-main-background);\n}\n\n.cell:hover {\n    border-color: var(--color-primary-element);\n}\n\n.cell:focus-visible {\n    outline: 2px solid var(--color-primary-element);\n    outline-offset: 1px;\n}\n\n.cell.out {\n    background: var(--color-background-hover);\n    color: var(--color-text-maxcontrast);\n    cursor: default;\n    opacity: 0.55;\n}\n\n.cell.out:hover {\n    border-color: var(--color-border-light, var(--color-border));\n}\n\n.cell.we {\n    background: var(--color-background-hover);\n}\n\n.cell.sel {\n    border-color: var(--color-primary-element);\n    box-shadow: 0 0 0 2px var(--color-primary-element-light);\n    background: var(--color-primary-element-light);\n}\n\n.cell.today .n {\n    color: var(--color-primary-element);\n    font-weight: 700;\n}\n\n.cell .n {\n    font-weight: 600;\n}\n\n.cell .hh {\n    margin-top: auto;\n    font-weight: 600;\n    font-size: 13px;\n    font-variant-numeric: tabular-nums;\n}\n\n.cell .mi {\n    margin-top: auto;\n    font-size: 12px;\n    font-weight: 600;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n}\n\n.cell .mi.vacation {\n    color: var(--wt-vacation);\n}\n\n.cell .mi.sick {\n    color: var(--wt-sick);\n}\n\n.cell .mi.h {\n    color: var(--wt-holiday);\n}\n\n.cell .mi.other {\n    color: var(--color-primary-element);\n}\n\n.leg {\n    display: flex;\n    gap: 16px;\n    flex-wrap: wrap;\n    margin-top: 13px;\n    font-size: 13px;\n    color: var(--color-text-maxcontrast);\n}\n\n.leg span {\n    display: inline-flex;\n    align-items: center;\n    gap: 7px;\n}\n\n.dot {\n    width: 9px;\n    height: 9px;\n    border-radius: 50%;\n    display: inline-block;\n}\n\n.dot.vacation {\n    background: var(--wt-vacation);\n}\n\n.dot.sick {\n    background: var(--wt-sick);\n}\n\n.dot.holiday {\n    background: var(--wt-holiday);\n}\n\n.dot.other {\n    background: var(--color-primary-element);\n}\n</style>\n"],"sourceRoot":""}]);
