['id', 'employeeId', 'createdAt', 'updatedAt', 'userId'])\n            const old = entry.oldValues || {}\n            const neu = entry.newValues || {}\n            const allKeys = [...new Set([...Object.keys(old), ...Object.keys(neu)])].filter(k => !skip.has(k))\n            return allKeys\n                .filter(k => String(old[k] ?? '') !== String(neu[k] ?? ''))\n                .map(k => ({ key: k, old: old[k] ?? '—', new: neu[k] ?? '—' }))\n        },\n        formatValues(values) {\n            if (!values || typeof values !== 'object') return '-'\n            const skip = new Set(['id', 'employeeId', 'createdAt', 'updatedAt', 'userId'])\n            return Object.entries(values)\n                .filter(([k, v]) => !skip.has(k) && v !== null && v !== '')\n                .map(([k, v]) => `${k}: ${v}`)\n                .join(', ') || '-'\n        },\n    },\n}\n</script>\n\n<style scoped>\n.audit-view {\n    padding: 20px;\n    padding-left: 50px;\n    max-width: 1600px;\n}\n\n.audit-card {\n    background: var(--color-main-background);\n    border: 1px solid var(--color-border-dark, var(--color-border));\n    border-radius: var(--border-radius-large, 12px);\n    padding: 8px 16px;\n    overflow-x: hidden;\n}\n\n.view-header {\n    display: flex;\n    align-items: center;\n    margin-bottom: 12px;\n}\n\n.view-header h2 {\n    margin: 0;\n}\n\n.view-toolbar {\n    display: flex;\n    align-items: center;\n    flex-wrap: wrap;\n    gap: 16px;\n    margin-bottom: 20px;\n}\n\n.view-header__controls {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    flex-wrap: wrap;\n}\n\n.audit-table {\n    width: 100%;\n    table-layout: fixed;\n    border-collapse: collapse;\n    font-size: 14px;\n}\n\n.audit-table th:nth-child(1) { width: 160px; } /* Zeitpunkt */\n.audit-table th:nth-child(2) { width: 130px; } /* Benutzer */\n.audit-table th:nth-child(3) { width: 110px; } /* Aktion */\n.audit-table th:nth-child(4) { width: 120px; } /* Typ */\n.audit-table th:n