                       </NcButton>\n                            <NcButton type=\"primary\" @click=\"submitPayout\">\n                                {{ t('zeitwerk', 'Auszahlung erfassen') }}\n                            </NcButton>\n                        </div>\n                    </div>\n                </NcModal>\n            </NcSettingsSection>\n\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\nimport NcLoadingIcon from '@nextcloud/vue/dist/Components/NcLoadingIcon.js'\nimport NcButton from '@nextcloud/vue/dist/Components/NcButton.js'\nimport NcSelect from '@nextcloud/vue/dist/Components/NcSelect.js'\nimport NcCheckboxRadioSwitch from '@nextcloud/vue/dist/Components/NcCheckboxRadioSwitch.js'\nimport NcModal from '@nextcloud/vue/dist/Components/NcModal.js'\nimport NcSettingsSection from '@nextcloud/vue/dist/Components/NcSettingsSection.js'\nimport NcDateTimePicker from '@nextcloud/vue/dist/Components/NcDateTimePicker.js'\nimport NcEmptyContent from '@nextcloud/vue/dist/Components/NcEmptyContent.js'\nimport Plus from 'vue-material-design-icons/Plus.vue'\nimport Account from 'vue-material-design-icons/Account.vue'\nimport AccountGroup from 'vue-material-design-icons/AccountGroup.vue'\nimport Folder from 'vue-material-design-icons/Folder.vue'\nimport Pencil from 'vue-material-design-icons/Pencil.vue'\nimport Close from 'vue-material-design-icons/Close.vue'\nimport CalendarBlank from 'vue-material-design-icons/CalendarBlank.vue'\nimport ChevronRight from 'vue-material-design-icons/ChevronRight.vue'\nimport ChevronDown from 'vue-material-design-icons/ChevronDown.vue'\nimport KeyVariant from 'vue-material-design-icons/KeyVariant.vue'\nimport OfficeBuilding from 'vue-material-design-icons/OfficeBuilding.vue'\nimport ClockCheckOutline from 'vue-material-design-icons/ClockCheckOutline.vue'\nimport { canTakeOverActuals, takeOverAndSave } from '../utils/carryoverTakeOver.js'\nimport { formatDuration } from '../utils/dutyRoster.js'\nimport CheckDecagram from 'vue-material-design-icons/CheckDecagram.vue'\nimport CoffeeOutline from 'vue-material-design-icons/CoffeeOutline.vue'\nimport FilePdfBox from 'vue-material-design-icons/FilePdfBox.vue'\nimport StarOutline from 'vue-material-design-icons/StarOutline.vue'\nimport CalendarStar from 'vue-material-design-icons/CalendarStar.vue'\nimport CalendarWeek from 'vue-material-design-icons/CalendarWeek.vue'\nimport Beach from 'vue-material-design-icons/Beach.vue'\nimport SwapHorizontalBold from 'vue-material-design-icons/SwapHorizontalBold.vue'\nimport CashMultiple from 'vue-material-design-icons/CashMultiple.vue'\nimport Car from 'vue-material-design-icons/Car.vue'\nimport { getFilePickerBuilder, FilePickerType, DialogBuilder } from '@nextcloud/dialogs'\nimport { mapGetters, mapActions } from 'vuex'\nimport SettingsService from '../services/SettingsService.js'\nimport HolidayService from '../services/HolidayService.js'\nimport DutyJobTemplateService from '../services/DutyJobTemplateService.js'\nimport EmployeeForm from '../components/EmployeeForm.vue'\nimport EmployeeList from '../components/EmployeeList.vue'\nimport BetriebsferienSettings from '../components/BetriebsferienSettings.vue'\nimport ProjectForm from '../components/ProjectForm.vue'\nimport ProjectList from '../components/ProjectList.vue'\nimport { showSuccessMessage, showErrorMessage, confirmAction } from '../utils/errorHandler.js'\nimport { getCurrentYear, getLocale, formatDateISO, getMonthName } from '../utils/dateUtils.js'\nimport YearlyCarryoverService from '../services/YearlyCarryoverService.js'\nimport OvertimePayoutService from '../services/OvertimePayoutService.js'\nimport ReportService from '../services/ReportService.js'\nimport TimeEntryService from '../services/TimeEntryService.js'\nimport InfoIcon from '../components/InfoIcon.vue'\nimport { formatMinutes, isValidTimeString, normalizeTimeInput } from '../utils/timeUtils.js'\nimport { ABSENCE_TYPE_LABELS } from '../constants.js'\nimport { countryOf, countryOptions, regionOptions, firstRegionOf, regionCodesOf } from '../utils/regions.js'\nimport { groupHolidays } from '../utils/holidayGroups.js'\n\nfunction round2(value) {\n    return Math.round(value * 100) / 100\n}\n\nexport default {\n    name: 'SettingsView',\n    components: {\n        InfoIcon,\n        NcLoadingIcon,\n        NcButton,\n        NcSelect,\n        NcCheckboxRadioSwitch,\n        NcModal,\n        NcSettingsSection,\n        NcDateTimePicker,\n        NcEmptyContent,\n        Plus,\n        Account,\n        AccountGroup,\n        Folder,\n        Pencil,\n        Close,\n        CalendarBlank,\n        ChevronRight,\n        ChevronDown,\n        KeyVariant,\n        OfficeBuilding,\n        ClockCheckOutline,\n        CheckDecagram,\n        CoffeeOutline,\n        FilePdfBox,\n        StarOutline,\n        CalendarStar,\n        CalendarWeek,\n        Beach,\n        SwapHorizontalBold,\n        CashMultiple,\n        Car,\n        EmployeeForm,\n        EmployeeList,\n        BetriebsferienSettings,\n        ProjectForm,\n        ProjectList,\n    },\n    data() {\n        return {\n            loading: false,\n            settings: {},\n            activeSection: null,\n            holidayYear: getCurrentYear(),\n            showEmployeeForm: false,\n            editingEmployee: null,\n            showProjectForm: false,\n            editingProject: null,\n            availablePrincipals: [],\n            hrManagers: [],\n            previousHrManagers: [],\n            // PDF-Archiv-Status (#323)\n            archiveStatus: { configured: false, pending: 0, failed: 0, jobs: [] },\n            archiveLoading: false,\n            archiveRetryingId: null,\n            // Dienstplan-Vorlagen\n            dutyTemplates: [],\n            loadingTemplates: false,\n            showTemplateForm: false,\n            editingTemplate: null,\n            templateErrors: {},\n            templateFormData: {\n                title: '',\n        