null\n            this.templateErrors = {}\n        },\n        templatePayload() {\n            return {\n                title: this.templateFormData.title.trim(),\n                startTime: this.templateFormData.startTime.trim() || null,\n                durationMinutes: this.templateFormData.durationMinutes || null,\n                note: this.templateFormData.note.trim() || null,\n                onCall: !!this.templateFormData.onCall,\n                isVisible: !!this.templateFormData.isVisible,\n            }\n        },\n        async saveTemplate() {\n            this.templateErrors = {}\n            this.templateFormData.startTime = normalizeTimeInput(this.templateFormData.startTime)\n            const startTime = this.templateFormData.startTime.trim()\n            if (startTime && !isValidTimeString(startTime)) {\n                this.$set(this.templateErrors, 'startTime', this.t('zeitwerk', 'Ungültige Uhrzeit (HH:MM)'))\n                return\n            }\n            try {\n                if (this.editingTemplate) {\n                    await DutyJobTemplateService.update(this.editingTemplate.id, this.templatePayload())\n                } else {\n                    await DutyJobTemplateService.create(this.templatePayload())\n                }\n                showSuccessMessage(this.t('zeitwerk', 'Vorlage gespeichert'))\n                this.closeTemplateForm()\n                await this.loadDutyTemplates()\n            } catch (error) {\n                // Feldfehler aus dem Backend direkt am Feld zeigen, Rest als Toast\n                if (error.errors) {\n                    const mapped = {}\n                    for (const [field, messages] of Object.entries(error.errors)) {\n                        mapped[field] = Array.isArray(messages) ? messages[0] : String(messages)\n                    }\n                    this.templateErrors = mapped\n                } else {\n                    showErrorMessage(error.message)\n                }\n            }\n        },\n        async toggleTemplateVisible(template, isVisible) {\n            try {\n                await DutyJobTemplateService.update(template.id, {\n                    title: template.title,\n                    startTime: template.startTime,\n                    durationMinutes: template.durationMinutes,\n                    note: template.note,\n                    onCall: !!template.onCall,\n                    isVisible,\n                })\n                await this.loadDutyTemplates()\n            } catch (error) {\n                showErrorMessage(error.message)\n                await this.loadDutyTemplates()\n            }\n        },\n        confirmDeleteTemplate(template) {\n            const dialog = new DialogBuilder()\n                .setName(this.t('zeitwerk', 'Vorlage löschen'))\n                .setText(this.t('zeitwerk', 'Vorlage «{title}» wirklich löschen? Bereits eingeplante Aufträge bleiben bestehen.', { title: template.title }))\n                .setButtons([\n                    {\n                        label: this.t('zeitwerk', 'Abbrechen'),\n                        type: 'secondary',\n                        callback: () => {},\n                    },\n                    {\n                        label: this.t('zeitwerk', 'Löschen'),\n                        type: 'error',\n                        callback: async () => {\n                            try {\n                                await DutyJobTemplateService.delete(template.id)\n                                showSuccessMessage(this.t('zeitwerk', 'Vorlage gelöscht'))\n                                await this.loadDutyTemplates()\n                            } catch (error) {\n                                showErrorMessage(error.message)\n                            }\n                        },\n                    },\n                ])\n                .build()\n\n            dialog.show()\n        },\n        // Holiday management methods\n        async loadHolidays() {\n            this.loadingHolidays = true\n            try {\n                this.holidays = await HolidayService.getByYear(this.holidayYear)\n            } catch (error) {\n                console.error('Failed to load holidays:', error)\n                this.holidays = []\n            } finally {\n                this.loadingHolidays = false\n            }\n        },\n        filterHolidays() {\n            // filteredHolidays is a computed property, so this just triggers reactivity\n        },\n        formatDate(dateStr) {\n            if (!dateStr) return ''\n            const date = new Date(dateStr)\n            return date.toLocaleDateString(getLocale(), { day: '2-digit', month: '2-digit', year: 'numeric' })\n        },\n        openHolidayForm(holiday) {\n            this.editingHoliday = holiday\n            if (holiday) {\n                this.holidayFormData = {\n                    date: new Date(holiday.date),\n                    name: holiday.name,\n                    federalStates: [holiday.federalState],\n                    scope: holiday.scope ?? 1.0,\n                }\n            } else {\n                this.holidayFormData = {\n                    date: null,\n                    name: '',\n                    federalStates: regionCodesOf(this.regions, this.defaultCountry),\n                    scope: 1.0,\n                }\n            }\n            this.showHolidayForm = true\n        },\n        closeHolidayForm() {\n            this.showHolidayForm = false\n            this.editingHoliday = null\n        },\n        selectCountryStates(country) {\n            const codes = regionCodesOf(this.regions, country)\n            this.holidayFormData.federalStates = Array.from(new Set([...this.holidayFormData.federalStates, ...codes]))\n        },\n        deselectCountryStates(country) {\n            const codes = new Set(regionCodesOf(this.regions, country))\n            this.holidayFormData.federalStates = this.holidayFormData.federalStates.filter(s => !codes.has(s))\n        },\n        toggleState(stateId, checked) {\n            if (checked) {\n                if (!this.holidayFormData.federalStates.includes(stateId)) {\n                    this.holidayFormData.federalStates.push(stateId)\n                }\n            } else {\n                this.holidayFormData.federalStates = this.holidayFormData.federalStates.filter(s => s !== stateId)\n            }\n        },\n        async saveHoliday() {\n            try {\n                // formatDateISO nutzt lokale Datumsteile statt UTC → kein -1-Tag-Shift in UTC+x (#273).\n                const dateStr = this.holidayFormData.date instanceof Date\n                    ? formatDateISO(this.holidayFormData.date)\n                    : this.holidayFormData.date\n\n                if (this.editingHoliday) {\n                    // Check if editing a group (multiple holidays)\n                    const holidayIds = this.editingHoliday.groupHolidayIds || [this.editingHoliday.id]\n                    for (const id of holidayIds) {\n                        await HolidayService.update(id, {\n                            date: dateStr,\n                            name: this.holidayFormData.name,\n                            scope: this.holidayFormData.scope,\n                        })\n                    }\n                    showSuccessMessage(\n                        this.t('zeitwerk', '{count} Feiertag(e) aktualisiert', { count: holidayIds.length })\n                    )\n                } else {\n                    await HolidayService.create({\n                        date: dateStr,\n                        name: this.holidayFormData.name,\n                        federalStates: this.holidayFormData.federalStates,\n                        scope: this.holidayFormData.scope,\n                    })\n                    showSuccessMessage(this.t('zeitwerk', 'Feiertag erstellt'))\n                }\n                this.closeHolidayForm()\n                await this.loadHolidays()\n            } catch (error) {\n                showErrorMessage(error.message)\n            }\n        },\n        toggleGroupExpand(key) {\n            const index = this.expandedGroups.indexOf(key)\n            if (index === -1) {\n                this.expandedGroups.push(key)\n            } else {\n                this.expandedGroups.splice(index, 1)\n            }\n        },\n        openHolidayGroupForm(group) {\n            // For editing a group, we edit the first holiday as representative\n            // User can only change date, name, scope (applied to all holidays in group)\n            const firstHoliday = group.holidays[0]\n            this.editingHoliday = {\n                ...firstHoliday,\n                // Store all holiday IDs for bulk update\n                groupHolidayIds: group.holidays.map(h => h.id),\n            }\n            this.holidayFormData = {\n                date: new Date(firstHoliday.date),\n                name: firstHoliday.name,\n                federalStates: group.states,\n                scope: firstHoliday.scope ?? 1.0,\n            }\n            this.showHolidayForm = true\n        },\n        async confirmDeleteHolidayGroup(group) {\n            const message = this.t('zeitwerk', 'Möchten Sie den Feiertag \"{name}\" ({count} Regionen) wirklich löschen?', {\n                name: group.name,\n                count: group.states.length,\n            })\n\n            const dialog = new DialogBuilder()\n                .setName(this.t('zeitwerk', 'Feiertag löschen'))\n                .setText(message)\n                .setButtons([\n                    {\n                        label: this.t('zeitwerk', 'Abbrechen'),\n                        type: 'secondary',\n                        callback: () => {},\n                    },\n                    {\n                        label: this.t('zeitwerk', 'Löschen'),\n                        type: 'error',\n                        callback: async () => {\n                            await this.deleteHolidayGroup(group)\n                        },\n                    },\n                ])\n                .build()\n\n            dialog.show()\n        },\n        async deleteHolidayGroup(group) {\n            if (!group) return\n            try {\n                // Delete all holidays in the group\n                for (const holiday of group.holidays) {\n                    await HolidayService.delete(holiday.id)\n                }\n                showSuccessMessage(\n                    this.t('zeitwerk', '{count} Feiertag(e) gelöscht', {\n                        count: group.holidays.length,\n                    })\n                )\n                await this.loadHolidays()\n            } catch (error) {\n                showErrorMessage(error.message)\n            }\n        },\n\n        // Yearly Carryover\n        async loadCarryovers() {\n            // The target year is bound to the rows that are built from it: a year\n            // change while requests are in flight must neither show stale rows\n            // nor let a queued save write to the newly selected year.\n            const targetYear = this.carryoverYear\n            // Only the most recent load may apply: a fast A -> B -> A switch starts\n            // two loads for A, and the older response must not overwrite rows\n            // (and edits made since) when it arrives late.\n            const loadSeq = ++this.carryoverLoadSeq\n            try {\n                const sourceYear = targetYear - 1\n                const [carryovers, teamYearData] = await Promise.all([\n                    YearlyCarryoverService.getByYear(targetYear),\n                    ReportService.getTeamYear(sourceYear),\n                ])\n                if (loadSeq !== this.carryoverLoadSeq || targetYear !== this.carryoverYear) {\n                    return // superseded by a newer load\n                }\n\n                const carryoverMap = {}\n                ;(carryovers || []).forEach(c => { carryoverMap[c.employeeId] = c })\n\n                // wasActive: must have schedule in source year AND real time entries\n                // Schedule check comes from backend (wasActiveInSourceYear)\n                // Real data check: at least one month with submitted/approved/rejected status\n                const scheduleMap = {}\n                ;(carryovers || []).forEach(c => { scheduleMap[c.employeeId] = c.wasActiveInSourceYear || false })\n\n                const realDataMap = {}\n                ;(teamYearData || []).forEach(r => {\n                    const hasRealData = r.months?.some(m =>\n                        m.status === 'submitted' || m.status === 'approved' || m.status === 'rejected'\n                    ) || false\n                    realDataMap[r.employee.id] = hasRealData\n                    // If has real data, also counts as having schedule\n                    if (hasRealData && !(r.employee.id in scheduleMap)) {\n                        scheduleMap[r.employee.id] = true\n                    }\n                })\n\n                const activityMap = {}\n                for (const empId of Object.keys({ ...scheduleMap, ...realDataMap })) {\n                    activityMap[empId] = (scheduleMap[empId] || false) && (realDataMap[empId] || false)\n                }\n\n                // Build actuals from team-year report\n                // totalOvertimeMinutes includes carryover — subtract for pure year value\n                const actualsMap = {}\n                ;(teamYearData || []).forEach(r => {\n                    const pureOvertimeMinutes = (r.totalOvertimeMinutes || 0) - (r.carryoverMinutes || 0)\n                    actualsMap[r.employee.id] = {\n                        overtimeHours: round2(pureOvertimeMinutes / 60),\n                        vacationRemaining: r.vacationStats?.remaining ?? null,\n                    }\n                })\n\n                // Year closed status — only for employees with real data\n                let allClosed = true\n                let hasAnyRealData = false\n                ;(teamYearData || []).forEach(r => {\n                    if (realDataMap[r.employee.id]) {\n                        hasAnyRealData = true\n                        r.months?.forEach(m => {\n                            if (m.overtimeMinutes !== null && m.status !== 'approved') {\n                                allClosed = false\n                            }\n                        })\n                    }\n                })\n                this.carryoverSourceYearStatus = hasAnyRealData ? (allClosed ? 'closed' : 'open') : null\n\n                this.carryoverEmployees = this.employees.map(emp => {\n                    const existing = carryoverMap[emp.id]\n                    const wasActive = activityMap[emp.id] || false\n                    const actuals = actualsMap[emp.id] || {}\n                    const overtimeHours = existing ? existing.overtimeHours : 0\n                    const vacationDays = existing ? existing.vacationDays : 0\n                    const note = existing ? (existing.note || '') : ''\n                    return {\n                        employeeId: emp.id,\n                        year: targetYear,\n                        carryoverId: existing ? existing.id : null,\n                        fullName: `${emp.firstName} ${emp.lastName}`,\n                        overtimeHours,\n                        vacationDays,\n                        note,\n                        isLocked: existing ? existing.isLocked : false,\n                        wasActive,\n                        actualOvertimeHours: wasActive ? (actuals.overtimeHours ?? null) : null,\n                        actualVacationRemaining: wasActive ? (actuals.vacationRemaining ?? null) : null,\n                        hasValues: !!(existing && (existing.overtimeMinutes !== 0 || existing.vacationDays !== 0 || existing.note)),\n                    }\n                }).map(row => {\n                    // A save for this row may still be running or queued: the server\n                    // state is behind the fields, so keep the unsaved edits instead of\n                    // reverting them to what the (stale) response reports.\n                    const key = this.carryoverKey(row)\n                    if (this.carryoverSaving[key] || this.carryoverQueued[key]) {\n                        const shown = this.carryoverEmployees.find(r => this.carryoverKey(r) === key)\n                        if (shown) {\n                            row.overtimeHours = shown.overtimeHours\n                            row.vacationDays = shown.vacationDays\n                            row.note = shown.note\n                            row.carryoverId = row.carryoverId || shown.carryoverId\n                            row.hasValues = row.overtimeHours !== 0 || row.vacationDays !== 0 || !!row.note\n                        }\n                    }\n                    return row\n                })\n            } catch (error) {\n                console.error('Failed to load carryovers:', error)\n            }\n        },\n        /** Requests are tracked per (year, employee): rows of different years never share state. */\n        carryoverKey(emp) {\n            return `${emp.year}:${emp.employeeId}`\n        },\n        /** The row object currently shown for a key (rows are rebuilt on every load). */\n        currentCarryoverRow(emp) {\n            return this.carryoverEmployees.find(r => r.year === emp.year && r.employeeId === emp.employeeId) || emp\n        },\n        /**\n         * Speichert die Zeile. Laeuft fuer diese Zeile bereits ein Speichern,\n         * wird kein paralleler zweiter Request gestartet (eine Zeile ohne ID,\n         * etwa direkt nach «Eintragen», koennte sonst doppelt angelegt werden).\n         * Stattdessen wird nach dem laufenden Request genau ein Folge-Speichern\n         * mit den dann aktuellen Feldwerten angehaengt, damit spaetere\n         * Aenderungen nicht verloren gehen und «Durchfuehren» nie einen\n         * veralteten Stand sperrt.\n         * @return {Promise<boolean>} true, wenn der aktuelle Stand gespeichert ist\n         */\n        autoSaveCarryover(emp) {\n            const id = this.carryoverKey(emp)\n            const inFlight = this.carryoverSaving[id]\n            if (inFlight) {\n                if (!this.carryoverQueued[id]) {\n                    const queued = inFlight.then(() => {\n                        this.$delete(this.carryoverQueued, id)\n                        // Save the row as it is NOW (latest edits, current object).\n                        return this.autoSaveCarryover(this.currentCarryoverRow(emp))\n                    })\n                    this.$set(this.carryoverQueued, id, queued)\n                }\n                return this.carryoverQueued[id]\n            }\n            const run = (async () => {\n                try {\n                    const result = await YearlyCarryoverService.upsert(\n                        emp.employeeId,\n                        emp.year,\n                        Math.round((emp.overtimeHours || 0) * 60),\n                        emp.vacationDays || 0,\n                        emp.note || null,\n                    )\n                    emp.carryoverId = result.id\n                    emp.hasValues = !!(result.overtimeMinutes !== 0 || result.vacationDays !== 0 || result.note)\n                    return true\n                } catch (error) {\n                    showErrorMessage(error.message)\n                    return false\n                } finally {\n                    this.$delete(this.carryoverSaving, id)\n                }\n            })()\n            this.$set(this.carryoverSaving, id, run)\n            return run\n        },\n        /**\n         * «Eintragen»: Ist-Werte des Vorjahres in die Uebertrags-Felder uebernehmen\n         * und wie eine Feldaenderung speichern (danach erscheint «Durchfuehren»).\n         * Schlaegt das Speichern fehl, setzt takeOverAndSave die Felder zurueck,\n         * damit die Zeile nicht ohne Button mit ungespeicherten Werten haengt.\n         */\n        takeOverCarryover(emp) {\n            if (this.carryoverLocking[this.carryoverKey(emp)]) return Promise.resolve(false)\n            return takeOverAndSave(emp, row => this.autoSaveCarryover(row), row => this.currentCarryoverRow(row))\n        },\n        canTakeOverActuals,\n        async lockCarryover(emp) {\n            const key = this.carryoverKey(emp)\n            if (this.carryoverLocking[key]) return\n            this.$set(this.carryoverLocking, key, true)\n            try {\n                // A save may still be in flight or queued (@change or «Eintragen»\n                // right before the click): persist the current field values first,\n                // then lock.\n                if (this.carryoverSaving[key] || this.carryoverQueued[key] || !emp.carryoverId) {\n                    if (!(await this.autoSaveCarryover(emp))) {\n                        return\n                    }\n                }\n                if (!emp.carryoverId) return\n                await YearlyCarryoverService.lock(emp.carryoverId)\n                emp.isLocked = true\n                showSuccessMessage(this.t('zeitwerk', 'Übertrag durchgeführt'))\n            } catch (error) {\n                showErrorMessage(error.message)\n            } finally {\n                this.$delete(this.carryoverLocking, key)\n            }\n        },\n        openCancelModal(emp) {\n            this.cancellingEmployee = emp\n            this.cancelForm = {\n                overtimeHours: emp.overtimeHours,\n                vacationDays: emp.vacationDays,\n                reason: '',\n            }\n            this.showCancelModal = true\n        },\n        closeCancelModal() {\n            this.showCancelModal = false\n            this.cancellingEmployee = null\n        },\n        async submitCancel() {\n            if (!this.cancellingEmployee?.carryoverId) return\n            try {\n                await YearlyCarryoverService.cancel(\n                    this.cancellingEmployee.carryoverId,\n                    Math.round(this.cancelForm.overtimeHours * 60),\n                    this.cancelForm.vacationDays,\n                    this.cancelForm.reason,\n                )\n                showSuccessMessage(this.t('zeitwerk', 'Übertrag korrigiert'))\n                this.closeCancelModal()\n                await this.loadCarryovers()\n            } catch (error) {\n                showErrorMessage(error.message)\n            }\n        },\n        resizeTextarea(event) {\n            const el = event.target\n            el.style.height = 'auto'\n            el.style.height = el.scrollHeight + 'px'\n        },\n        /** Uebertrags-Stunden mit zwei Nachkommastellen (Minuten-genau), wie im Eingabefeld. */\n        formatCarryoverHours(value) {\n            if (value === null || value === undefined) return '–'\n            return Number(value).toFixed(2)\n        },\n        formatHours(value) {\n            if (value === null || value === undefined) return '–'\n            const sign = value >= 0 ? '+' : ''\n            return `${sign}${value.toFixed(1)}`\n        },\n        // ---- Überstunden-Auszahlung (#401) ----\n        async loadPayouts() {\n            try {\n                const [teamYearData, payouts] = await Promise.all([\n                    ReportService.getTeamYear(this.payoutYear),\n                    OvertimePayoutService.getByYear(this.payoutYear),\n                ])\n\n                this.payoutEmployees = (teamYearData || []).map(r => ({\n                    employeeId: r.employee.id,\n                    fullName: r.employee.fullName,\n                    saldoMinutes: r.totalOvertimeMinutes || 0,\n                    paidOutMinutes: r.paidOutMinutes || 0,\n                }))\n\n                const nameMap = {}\n                this.employees.forEach(e => { nameMap[e.id] = `${e.firstName} ${e.lastName}` })\n                this.payoutHistory = (payouts || []).map(p => ({\n                    ...p,\n                    employeeName: nameMap[p.employeeId] || `#${p.employeeId}`,\n                }))\n            } catch (error) {\n                console.error('Failed to load payouts:', error)\n            }\n        },\n        openPayoutModal(emp) {\n            this.payoutTarget = emp\n            this.payoutForm = {\n                hours: '',\n                date: formatDateISO(new Date()),\n                note: '',\n            }\n            this.payoutError = ''\n            this.showPayoutModal = true\n        },\n        closePayoutModal() {\n            this.showPayoutModal = false\n            this.payoutTarget = null\n        },\n        parsePayoutMinutes(str) {\n            const s = (str || '').trim().replace(',', '.')\n            if (s === '') return null\n            if (s.includes(':')) {\n                const [h, m] = s.split(':')\n                const mm = parseInt(m || '0', 10)\n                const hh = parseInt(h || '0', 10)\n                if (isNaN(hh) || isNaN(mm) || mm > 59) return null\n                return hh * 60 + mm\n            }\n            const f = parseFloat(s)\n            if (isNaN(f)) return null\n            return Math.round(f * 60)\n        },\n        async submitPayout() {\n            const minutes = this.parsePayoutMinutes(this.payoutForm.hours)\n            const saldo = this.payoutTarget?.saldoMinutes || 0\n            if (minutes === null || minutes <= 0) {\n                this.payoutError = this.t('zeitwerk', 'Bitte gültige Stunden eingeben.')\n                return\n            }\n            if (minutes > saldo) {\n                this.payoutError = this.t('zeitwerk', 'Die Auszahlung darf den verfügbaren Saldo nicht überschreiten.')\n                return\n            }\n            if (this.payoutForm.note.trim().length < 10) {\n                this.payoutError = this.t('zeitwerk', 'Bitte einen Grund mit mindestens 10 Zeichen angeben.')\n                return\n            }\n            try {\n                await OvertimePayoutService.create(\n                    this.payoutTarget.employeeId,\n                    this.payoutForm.date,\n                    minutes,\n                    this.payoutForm.note.trim(),\n                )\n                showSuccessMessage(this.t('zeitwerk', 'Auszahlung erfasst'))\n                this.closePayoutModal()\n                await this.loadPayouts()\n            } catch (error) {\n                this.payoutError = error.message\n            }\n        },\n        async deletePayout(payout) {\n            const confirmed = await confirmAction(\n                this.t('zeitwerk', 'Diese Auszahlung löschen? Der Überstundensaldo wird wieder erhöht.'),\n                this.t('zeitwerk', 'Auszahlung löschen'),\n                this.t('zeitwerk', 'Löschen'),\n                true,\n            )\n            if (!confirmed) return\n            try {\n                await OvertimePayoutService.delete(payout.id)\n                showSuccessMessage(this.t('zeitwerk', 'Auszahlung gelöscht'))\n                await this.loadPayouts()\n            } catch (error) {\n                showErrorMessage(error.message)\n            }\n        },\n        formatSignedHours(minutes) {\n            const sign = minutes >= 0 ? '+' : ''\n            return `${sign}${formatMinutes(minutes)}`\n        },\n        formatAbsHours(minutes) {\n            return formatMinutes(Math.abs(minutes))\n        },\n        formatDateDisplay(iso) {\n            if (!iso) return ''\n            return iso.split('-').reverse().join('.')\n        },\n    },\n}\n</script>\n\n<style scoped>\n.settings-view {\n    padding: 20px;\n    padding-left: 50px;\n    max-width: 1100px;\n}\n\n.view-header {\n    display: flex;\n    align