<template>
    <div class="employee-form">
        <h3>{{ isEdit ? t('zeitwerk', 'Mitarbeiter bearbeiten') : t('zeitwerk', 'Neuer Mitarbeiter') }}</h3>

        <div class="form-group">
            <label for="ncUser">{{ t('zeitwerk', 'Nextcloud-Benutzer') }}</label>
            <NcSelect id="ncUser"
                v-model="selectedUser"
                :options="userOptions"
                :placeholder="t('zeitwerk', 'Benutzer auswählen')"
                :clearable="false"
                :disabled="isEdit"
                label="label" />
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="firstName">{{ t('zeitwerk', 'Vorname') }} *</label>
                <input id="firstName"
                    v-model="form.firstName"
                    type="text"
                    class="input-field"
                    required>
            </div>
            <div class="form-group">
                <label for="lastName">{{ t('zeitwerk', 'Nachname') }} *</label>
                <input id="lastName"
                    v-model="form.lastName"
                    type="text"
                    class="input-field"
                    required>
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="email">{{ t('zeitwerk', 'E-Mail') }}</label>
                <input id="email"
                    v-model="form.email"
                    type="email"
                    class="input-field">
            </div>
            <div class="form-group">
                <label for="personnelNumber">{{ t('zeitwerk', 'Personalnummer') }}</label>
                <input id="personnelNumber"
                    v-model="form.personnelNumber"
                    type="text"
                    class="input-field">
            </div>
        </div>

        <div v-if="!isEdit" class="form-row">
            <div class="form-group">
                <label for="weeklyHours">{{ t('zeitwerk', 'Wochenstunden') }} <InfoIcon>{{ t('zeitwerk', 'Vertraglich vereinbarte Arbeitszeit pro Woche. Daraus berechnet Zeitwerk das tägliche Soll (Wochenstunden ÷ Arbeitstage pro Woche).') }}</InfoIcon> *</label>
                <input id="weeklyHours"
                    v-model.number="form.weeklyHours"
                    type="number"
                    min="0.5"
                    max="60"
                    step="0.5"
                    :class="['input-field', 'input-small', { 'input-error': !(form.weeklyHours > 0) }]"
                    required>
                <p v-if="!(form.weeklyHours > 0)" class="field-hint field-hint--error">
                    {{ t('zeitwerk', 'Wochenstunden müssen größer als 0 sein. Für eine vorübergehende Auszeit (z. B. Elternzeit) eine Abwesenheit erfassen statt 0 Stunden.') }}
                </p>
            </div>
            <div class="form-group">
                <label for="vacationDays">{{ t('zeitwerk', 'Urlaubstage') }} <InfoIcon>{{ t('zeitwerk', 'Jährlicher Urlaubsanspruch. Jeder genommene Urlaubstag wird davon abgezogen. Der Resturlaub wird in der Zeiterfassung angezeigt.') }}</InfoIcon> *</label>
                <input id="vacationDays"
                    v-model.number="form.vacationDays"
                    type="number"
                    min="0"
                    max="60"
                    class="input-field input-small"
                    required>
            </div>
        </div>

        <div v-if="isEdit" class="form-row">
            <div class="form-group">
                <label>{{ t('zeitwerk', 'Wochenstunden') }} <InfoIcon>{{ t('zeitwerk', 'Aktuell gültiger Wert aus dem Arbeitszeitprofil. Zum Ändern unten das Profil bearbeiten oder ein neues anlegen.') }}</InfoIcon></label>
                <input :value="form.weeklyHours"
                    type="text"
                    class="input-field input-small"
                    disabled>
            </div>
            <div class="form-group">
                <label>{{ t('zeitwerk', 'Urlaubstage') }} <InfoIcon>{{ t('zeitwerk', 'Aktuell gültiger Wert aus dem Arbeitszeitprofil. Zum Ändern unten das Profil bearbeiten oder ein neues anlegen.') }}</InfoIcon></label>
                <input :value="form.vacationDays"
                    type="text"
                    class="input-field input-small"
                    disabled>
            </div>
        </div>
        <p v-if="isEdit" class="field-hint">
            {{ t('zeitwerk', 'Wochenstunden und Urlaubstage ergeben sich aus dem Arbeitszeitprofil unten und werden dort gepflegt.') }}
        </p>

        <div class="form-row">
            <div class="form-group">
                <label for="workingDaysPerWeek">{{ t('zeitwerk', 'Arbeitstage pro Woche') }} <InfoIcon>{{ t('zeitwerk', 'An wie vielen Tagen pro Woche wird gearbeitet? Daraus und aus den Wochenstunden ergibt sich das tägliche Soll. Beispiel: 40 Std. auf 5 Tage = 8 Std./Tag, 30 Std. auf 4 Tage = 7,5 Std./Tag.') }}</InfoIcon></label>
                <input id="workingDaysPerWeek"
                    v-model.number="form.workingDaysPerWeek"
                    type="number"
                    min="1"
                    max="7"
                    class="input-field input-small">
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="country">{{ t('zeitwerk', 'Land') }} <InfoIcon>{{ t('zeitwerk', 'Land und Region legen fest, welche gesetzlichen Feiertage für diesen Mitarbeiter gelten. Bayern hat z.B. mehr Feiertage als Hamburg, das Tessin mehr als Zürich.') }}</InfoIcon> *</label>
                <NcSelect id="country"
                    v-model="selectedCountry"
                    :options="countryOptions"
                    :clearable="false"
                    label="label" />
            </div>
            <div class="form-group">
                <label for="federalState">{{ regionLabel }} *</label>
                <NcSelect id="federalState"
                    v-model="selectedFederalState"
                    :options="federalStateOptions"
                    :clearable="false"
                    label="label" />
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="supervisor">{{ t('zeitwerk', 'Vorgesetzter') }} <InfoIcon>{{ t('zeitwerk', 'Diese Person kann die Zeiteinträge und Abwesenheitsanträge dieses Mitarbeiters einsehen und genehmigen.') }}</InfoIcon></label>
                <NcSelect id="supervisor"
                    v-model="selectedSupervisor"
                    :options="supervisorOptions"
                    :placeholder="t('zeitwerk', 'Kein Vorgesetzter')"
                    label="label" />
            </div>
        </div>

        <div class="form-row">
            <div class="form-group">
                <label for="entryDate">{{ t('zeitwerk', 'Eintrittsdatum') }} <InfoIcon>{{ t('zeitwerk', 'Ab diesem Datum erscheint der Mitarbeiter in der Zeiterfassung. Für Monate davor werden keine Sollstunden berechnet.') }}</InfoIcon></label>
                <NcDateTimePicker id="entryDate"
                    v-model="form.entryDate"
                    type="date"
                    :format="'DD.MM.YYYY'" />
            </div>
            <div v-if="isEdit" class="form-group">
                <label for="exitDate">{{ t('zeitwerk', 'Austrittsdatum') }} <InfoIcon>{{ t('zeitwerk', 'Ab diesem Datum kann der Mitarbeiter keine neuen Einträge mehr erfassen. Alle bisherigen Daten bleiben erhalten.') }}</InfoIcon></label>
                <NcDateTimePicker id="exitDate"
                    v-model="form.exitDate"
                    type="date"
                    :format="'DD.MM.YYYY'" />
            </div>
        </div>

        <!-- Aktiv + Im Dienstplan links, Reihenfolge rechts daneben (unter dem Austrittsdatum) -->
        <div class="form-row">
            <div class="form-group">
                <NcCheckboxRadioSwitch v-if="isEdit" :checked.sync="form.isActive">
                    {{ t('zeitwerk', 'Aktiv') }} <InfoIcon>{{ t('zeitwerk', 'Inaktive Mitarbeiter können keine Zeiten mehr erfassen und tauchen nicht in Auswahllisten auf. Ihre bisherigen Daten und Berichte bleiben erhalten.') }}</InfoIcon>
                </NcCheckboxRadioSwitch>
                <NcCheckboxRadioSwitch :checked.sync="form.inDutyRoster">
                    {{ t('zeitwerk', 'Im Dienstplan') }} <InfoIcon>{{ t('zeitwerk', 'Der Mitarbeiter erscheint als Zeile im Wochenplan (nur relevant, wenn der Dienstplan in den Firmeneinstellungen aktiv ist).') }}</InfoIcon>
                </NcCheckboxRadioSwitch>
            </div>
            <div class="form-group">
                <template v-if="form.inDutyRoster">
                    <label for="dutyRosterOrder">{{ t('zeitwerk', 'Reihenfolge im Dienstplan') }} <InfoIcon>{{ t('zeitwerk', 'Kleinere Zahlen stehen weiter oben. Gleiche Zahlen werden nach Nachname sortiert.') }}</InfoIcon></label>
                    <input id="dutyRosterOrder"
                        v-model.number="form.dutyRosterOrder"
                        type="number"
                        min="0"
                        max="999"
                        step="1"
                        class="input-field input-small">
                </template>
            </div>
        </div>

        <WorkScheduleEditor v-if="isEdit && employee"
            :employee-id="employee.id"
            @updated="$emit('schedule-updated')" />

        <div class="form-actions">
            <NcButton type="tertiary" @click="cancel">
                {{ t('zeitwerk', 'Abbrechen') }}
            </NcButton>
            <NcButton type="primary" :disabled="!isValid" @click="save">
                {{ t('zeitwerk', 'Speichern') }}
            </NcButton>
        </div>
    </div>
</template>

<script>
import NcButton from '@nextcloud/vue/dist/Components/NcButton.js'
import NcSelect from '@nextcloud/vue/dist/Components/NcSelect.js'
import NcDateTimePicker from '@nextcloud/vue/dist/Components/NcDateTimePicker.js'
import NcCheckboxRadioSwitch from '@nextcloud/vue/dist/Components/NcCheckboxRadioSwitch.js'
import WorkScheduleEditor from './WorkScheduleEditor.vue'
import { mapGetters, mapActions } from 'vuex'
import { formatDateISO } from '../utils/dateUtils.js'
import { countryOf, countryOptions, regionOptions, regionLabelFor, firstRegionOf } from '../utils/regions.js'
import InfoIcon from '../components/InfoIcon.vue'

export default {
    name: 'EmployeeForm',
    components: {
        InfoIcon,
        NcButton,
        NcSelect,
        NcDateTimePicker,
        NcCheckboxRadioSwitch,
        WorkScheduleEditor,
    },
    props: {
        employee: {
            type: Object,
            default: null,
        },
        // Standard-Region aus den Firmendaten (#337): Vorauswahl fuer neue
        // Mitarbeitende (Regionscode DE-BY, CH-ZH). Bleibt frei aenderbar; im
        // Bearbeiten-Modus wird die am Mitarbeiter gespeicherte Region verwendet.
        defaultFederalState: {
            type: String,
            default: 'DE-BY',
        },
    },
    data() {
        return {
            form: {
                userId: '',
                firstName: '',
                lastName: '',
                email: '',
                personnelNumber: '',
                weeklyHours: 40,
                vacationDays: 30,
                workingDaysPerWeek: 5,
                supervisorId: null,
                federalState: this.defaultFederalState,
                entryDate: null,
                exitDate: null,
                isActive: true,
                inDutyRoster: false,
                dutyRosterOrder: 0,
            },
        }
    },
    computed: {
        ...mapGetters('employees', ['employees', 'availableUsers']),
        ...mapGetters('holidays', ['regions']),
        isEdit() {
            return !!this.employee
        },
        userOptions() {
            return this.availableUsers.map(u => ({
                id: u.user,
                label: u.displayName + (u.subname ? ` (${u.subname})` : ''),
                email: u.subname || '',
            }))
        },
        selectedUser: {
            get() {
                if (this.isEdit && this.employee) {
                    return {
                        id: this.employee.userId,
                        label: this.employee.fullName,
                    }
                }
                return this.userOptions.find(u => u.id === this.form.userId) || null
            },
            set(value) {
                this.form.userId = value?.id || ''
                // Pre-fill name from display name if empty
                if (value && !this.form.firstName && !this.form.lastName) {
                    const parts = value.label.split(' ')
                    if (parts.length >= 2) {
                        this.form.firstName = parts[0]
                        this.form.lastName = parts.slice(1).join(' ').replace(/\s*\(.*\)$/, '')
                    }
                }
                // Pre-fill email from NC profile if empty
                if (value?.email && !this.form.email) {
                    this.form.email = value.email
                }
            },
        },
        countryOptions() {
            return countryOptions(this.regions)
        },
        currentCountry() {
            return countryOf(this.form.federalState) || countryOf(this.defaultFederalState) || 'DE'
        },
        selectedCountry: {
            get() {
                return this.countryOptions.find(c => c.id === this.currentCountry) || null
            },
            set(value) {
                if (!value || value.id === this.currentCountry) {
                    return
                }
                // Landwechsel: erste Region des neuen Landes vorbelegen
                this.form.federalState = firstRegionOf(this.regions, value.id) || ''
            },
        },
        federalStateOptions() {
            return regionOptions(this.regions, this.currentCountry)
        },
        selectedFederalState: {
            get() {
                return this.federalStateOptions.find(s => s.id === this.form.federalState) || null
            },
            set(value) {
                this.form.federalState = value?.id || this.defaultFederalState
            },
        },
        regionLabel() {
            const labels = {
                Bundesland: this.t('zeitwerk', 'Bundesland'),
                Kanton: this.t('zeitwerk', 'Kanton'),
            }
            return labels[regionLabelFor(this.regions, this.currentCountry)] || this.t('zeitwerk', 'Region')
        },
        supervisorOptions() {
            return this.employees
                .filter(e => !this.employee || e.id !== this.employee.id)
                .filter(e => e.isActive)
                .map(e => ({
                    id: e.id,
                    label: e.fullName,
                }))
        },
        selectedSupervisor: {
            get() {
                return this.supervisorOptions.find(s => s.id === this.form.supervisorId) || null
            },
            set(value) {
                this.form.supervisorId = value?.id || null
            },
        },
        isValid() {
            const baseValid = (this.isEdit || this.form.userId)
                && this.form.firstName.trim()
                && this.form.lastName.trim()
                && this.form.federalState
            if (this.isEdit) {
                return baseValid
            }
            // New employee: weeklyHours must be > 0 (a 0-hour contract would create
            // a zero-hour work schedule and break every day/absence calculation).
            return baseValid && this.form.weeklyHours > 0 && this.form.vacationDays >= 0
        },
    },
    watch: {
        employee: {
            immediate: true,
            handler(employee) {
                if (employee) {
                    this.form = {
                        userId: employee.userId,
                        firstName: employee.firstName,
                        lastName: employee.lastName,
                        email: employee.email || '',
                        personnelNumber: employee.personnelNumber || '',
                        weeklyHours: employee.weeklyHours,
                        vacationDays: employee.vacationDays,
                        workingDaysPerWeek: employee.workingDaysPerWeek ?? 5,
                        supervisorId: employee.supervisorId,
                        federalState: employee.federalState,
                        entryDate: employee.entryDate ? new Date(employee.entryDate) : null,
                        exitDate: employee.exitDate ? new Date(employee.exitDate) : null,
                        isActive: employee.isActive,
                        inDutyRoster: !!employee.inDutyRoster,
                        dutyRosterOrder: employee.dutyRosterOrder ?? 0,
                    }
                } else {
                    this.resetForm()
                }
            },
        },
    },
    created() {
        this.$store.dispatch('holidays/fetchRegions')
        this.$store.dispatch('employees/fetchEmployees')
        if (!this.isEdit) {
            this.$store.dispatch('employees/fetchAvailableUsers')
        }
    },
    methods: {
        ...mapActions('employees', ['createEmployee', 'updateEmployee']),
        resetForm() {
            this.form = {
                userId: '',
                firstName: '',
                lastName: '',
                email: '',
                personnelNumber: '',
                weeklyHours: 40,
                vacationDays: 30,
                workingDaysPerWeek: 5,
                supervisorId: null,
                federalState: this.defaultFederalState,
                entryDate: null,
                exitDate: null,
                isActive: true,
                inDutyRoster: false,
                dutyRosterOrder: 0,
            }
        },
        cancel() {
            this.$emit('cancel')
        },
        async save() {
            try {
                const data = {
                    userId: this.form.userId,
                    firstName: this.form.firstName.trim(),
                    lastName: this.form.lastName.trim(),
                    email: this.form.email.trim() || null,
                    personnelNumber: this.form.personnelNumber.trim() || null,
                    weeklyHours: this.form.weeklyHours,
                    vacationDays: this.form.vacationDays,
                    workingDaysPerWeek: this.form.workingDaysPerWeek,
                    supervisorId: this.form.supervisorId,
                    federalState: this.form.federalState,
                    entryDate: this.form.entryDate ? formatDateISO(this.form.entryDate) : null,
                    exitDate: this.form.exitDate ? formatDateISO(this.form.exitDate) : null,
                    isActive: this.form.isActive,
                    inDutyRoster: this.form.inDutyRoster,
                    dutyRosterOrder: Number(this.form.dutyRosterOrder) || 0,
                }

                if (this.isEdit) {
                    await this.updateEmployee({ id: this.employee.id, data })
                } else {
                    await this.createEmployee(data)
                }

                // Die Dienstplan-Zugehoerigkeit bestimmt mit, ob der Nutzer den
                // Wochenplan sieht — Berechtigungen sonst erst nach Reload aktuell.
                if (this.form.inDutyRoster !== (this.employee?.inDutyRoster ?? false)) {
                    await this.$store.dispatch('permissions/fetchPermissions')
                }

                this.$emit('saved')
            } catch (error) {
                console.error('Failed to save employee:', error)
            }
        },
    },
}
</script>

<style scoped>
.employee-form {
    padding: 16px;
}

.employee-form h3 {
    margin: 0 0 16px 0;
}

.form-group {
    margin-bottom: 16px;
}

.form-group label {
    display: block;
    margin-bottom: 4px;
    font-weight: 500;
}

.form-row {
    display: flex;
    gap: 16px;
}

.form-row .form-group {
    flex: 1;
}

.input-field {
    width: 100%;
    padding: 8px;
    border: 1px solid var(--color-border);
    border-radius: var(--border-radius);
    background: var(--color-main-background);
    color: var(--color-main-text);
}

.input-small {
    width: 8rem;
}

.field-hint {
    margin: -8px 0 16px 0;
    color: var(--color-text-maxcontrast);
    font-size: 0.9em;
}

.field-hint--error {
    color: var(--color-error, #dc2626);
}

.input-error {
    border-color: var(--color-error, #dc2626) !important;
