rt default {\n    name: 'ProjectForm',\n    components: {\n        NcButton,\n        NcCheckboxRadioSwitch,\n        NcSelect,\n    },\n    props: {\n        project: {\n            type: Object,\n            default: null,\n        },\n    },\n    data() {\n        return {\n            form: {\n                name: '',\n                code: null,\n                description: null,\n                customer: null,\n                color: null,\n                isActive: true,\n                isBillable: true,\n                allEmployees: true,\n                isFieldWork: false,\n                isExtern: false,\n                memberIds: [],\n            },\n        }\n    },\n    computed: {\n        ...mapGetters('employees', ['employees']),\n        isEdit() {\n            return !!this.project\n        },\n        isValid() {\n            return this.form.name.trim().length > 0\n        },\n        employeeOptions() {\n            return this.employees.map(e => ({\n                id: e.id,\n                label: `${e.firstName} ${e.lastName}`.trim() || e.userId,\n            }))\n        },\n        selectedMembers: {\n            get() {\n                return this.employeeOptions.filter(o => this.form.memberIds.includes(o.id))\n            },\n            set(value) {\n                this.form.memberIds = (value || []).map(o => o.id)\n            },\n        },\n        bookingMode: {\n            get() {\n                return this.form.allEmployees ? 'all' : 'selected'\n            },\n            set(value) {\n                this.form.allEmployees = value === 'all'\n            },\n        },\n    },\n    watch: {\n        project: {\n            immediate: true,\n            handler(project) {\n                if (project) {\n                    this.form = {\n                        name: project.name || '',\n                        code: project.code || null,\n                        description: project.description || null,\n           