mployees,\n                    isFieldWork: this.form.isFieldWork,\n                    isExtern: this.form.isExtern,\n                    memberIds: this.form.allEmployees ? [] : this.form.memberIds,\n                }\n\n                if (this.isEdit) {\n                    await this.updateProject({ id: this.project.id, data })\n                    showSuccessMessage(this.t('zeitwerk', 'Projekt aktualisiert'))\n                } else {\n                    await this.createProject(data)\n                    showSuccessMessage(this.t('zeitwerk', 'Projekt erstellt'))\n                }\n\n                this.$emit('saved')\n            } catch (error) {\n                showErrorMessage(error.message || this.t('zeitwerk', 'Fehler beim Speichern'))\n            }\n        },\n    },\n}\n</script>\n\n<style scoped>\n.project-form {\n    padding: 20px;\n}\n\n.project-form-header {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 16px;\n    margin-bottom: 4px;\n}\n\n.project-form-header h3 {\n    margin: 0;\n}\n\n.header-hint {\n    margin: 0 0 20px;\n    font-size: 0.85em;\n    color: var(--color-text-maxcontrast);\n}\n\n.form-group-label {\n    display: block;\n    margin-bottom: 8px;\n    font-weight: 500;\n}\n\n.member-select {\n    margin-top: 8px;\n    padding-left: 28px;\n}\n\n.form-group {\n    margin-bottom: 16px;\n}\n\n.form-group label {\n    display: block;\n    margin-bottom: 4px;\n    font-weight: 500;\n}\n\n.form-row {\n    display: flex;\n    gap: 16px;\n    align-items: flex-start;\n}\n\n.form-row .form-group {\n    flex: 1;\n}\n\n.input-field {\n    width: 100%;\n    padding: 8px;\n    border: 1px solid var(--color-border);\n    border-radius: var(--border-radius);\n    background: var(--color-main-background);\n    color: var(--color-main-text);\n}\n\n.textarea-field {\n    resize: vertical;\n    font-family: inherit;\n}\n\n.color-picker-row {\n    display: flex;\n    align-items: center;\n    gap: 8px;\